	'audience_about_items'=>['Пункты о занятиях',[['caption'=>'Пункт','fields'=>[f('title','Заголовок'),f('description','Описание','textarea')]]],[['header'=>'Заголовок','dataIndex'=>'title','width'=>300,'renderer'=>'Ext.util.Format.htmlEncode'],['header'=>'Описание','dataIndex'=>'description','width'=>550,'renderer'=>'Ext.util.Format.htmlEncode']],'Добавляйте пункты и меняйте порядок строк.'],
	'audience_faq'=>['Вопросы и ответы',[['caption'=>'Вопрос','fields'=>[f('question','Вопрос'),f('answer','Ответ (HTML)','textarea','Допускаются абзацы <p>, ссылки и теги MODX/ClientConfig.')]]],[['header'=>'Вопрос','dataIndex'=>'question','width'=>350,'renderer'=>'Ext.util.Format.htmlEncode'],['header'=>'Ответ','dataIndex'=>'answer','width'=>550,'renderer'=>'Ext.util.Format.htmlEncode']],'FAQ именно этой аудитории. Порядок строк соответствует порядку на сайте.'],
];
$category=$modx->getObject(modCategory::class,['category'=>'Аудитория'])?:$modx->newObject(modCategory::class);$category->set('category','Аудитория');if(!$category->save())throw new RuntimeException('Category save failed');
$file=$root.'cms/template-registry.json';$reg=json_decode(file_get_contents($file),true);
foreach($defs as $name=>[$caption,$formTabs,$columns,$description]){
	$tv=$modx->getObject(modTemplateVar::class,['name'=>$name])?:$modx->newObject(modTemplateVar::class);$tv->fromArray(['name'=>$name,'caption'=>$caption,'category'=>$category->get('id'),'description'=>$description,'type'=>'migx','default_text'=>'','display'=>'default','rank'=>array_search($name,array_keys($defs)),'input_properties'=>['formtabs'=>json_encode($formTabs,JSON_UNESCAPED_UNICODE),'columns'=>json_encode($columns,JSON_UNESCAPED_UNICODE),'btntext'=>$name==='audience_blocks'?'Добавить настройки':'Добавить запись']]);if(!$tv->save())throw new RuntimeException('TV save failed');$id=(int)$tv->get('id');$reg['fields'][$name]=$id;$criteria=['tmplvarid'=>$id,'templateid'=>16];if(!$modx->getObject(modTemplateVarTemplate::class,$criteria)){$link=$modx->newObject(modTemplateVarTemplate::class);$link->fromArray($criteria,'',true,true);if(!$link->save())throw new RuntimeException('TV assignment failed');}
	foreach($modx->getCollection(modResource::class,['template'=>16,'deleted'=>0]) as $r)if(!$modx->getObject(modTemplateVarResource::class,['tmplvarid'=>$id,'contentid'=>$r->get('id')])){if(!isset($seeds[$r->get('id')][$name]))throw new RuntimeException('Seed missing');if(!$r->setTVValue($name,json_encode($seeds[$r->get('id')][$name],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)))throw new RuntimeException('Seed save failed');}
}
// The short description belongs to the direction, shared by all audience pages.
$tv=$modx->getObject(modTemplateVar::class,['name'=>'direction_blocks']);$props=$tv->get('input_properties');$formTabs=json_decode($props['formtabs'],true);foreach($formTabs as &$tab)if($tab['caption']==='Карточка направления'&&!in_array('card_audience_description',array_column($tab['fields'],'field'),true))$tab['fields'][]=f('card_audience_description','Краткое описание на страницах аудитории','textarea','Если пусто — описание из списка направлений.');unset($tab);$props['formtabs']=json_encode($formTabs,JSON_UNESCAPED_UNICODE);$tv->set('input_properties',$props);if(!$tv->save())throw new RuntimeException('Direction card config save failed');
foreach($directionSeed as $id=>$description){$r=$modx->getObject(modResource::class,$id);$rows=json_decode($r->getTVValue('direction_blocks'),true);if(!array_key_exists('card_audience_description',$rows[0])){$rows[0]['card_audience_description']=$description;$r->setTVValue('direction_blocks',json_encode($rows,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}}
