if(!str_contains($html,'tvname=`audience_blocks`')){$html='[[$head]]'."\n".'[[$header]]'."\n<main id=\"main\">\n";foreach(['audienceHero','audienceAbout','audienceDirections','audienceFaq'] as $name)$html.="\t[[!getImageList? &tvname=`audience_blocks` &tpl=`$name` &limit=`1` &totalVar=`audienceBlocksTotal`]]\n";$html.="\t".'[[$trainingCta]]'."\n</main>\n".'[[$footer]]'."\n";$template->set('content',$html);if(!$template->save())throw new RuntimeException('Template save failed');}
for($i=1;$i<=24;$i++){$name=sprintf('audience_field_%02d',$i);$old=$modx->getObject(modTemplateVar::class,['name'=>$name]);if(!$old)continue;$link=$modx->getObject(modTemplateVarTemplate::class,['tmplvarid'=>$old->get('id'),'templateid'=>16]);if($link)$link->remove();if(!$modx->getCount(modTemplateVarTemplate::class,['tmplvarid'=>$old->get('id')])){$old->remove();unset($reg['fields'][$name]);}}
$reg['chunks']=array_values(array_unique(array_merge($reg['chunks'],$names)));file_put_contents($file,json_encode($reg,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));$modx->cacheManager->refresh();echo "Audience pages grouped into three MIGX editors.\n";
